package com.lsi.businesscard;
import android.app.*;
import android.content.*;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import java.io.File;
import java.util.*;
/** Select sample, connect columns, preview, confirm. The source app need not be CamCard. */
public class ImportActivity extends Activity {
 private List<Map<String,String>> rows;private List<String> headers;private final Map<String,String> mapping=new LinkedHashMap<>();private String source="이전 앱";private File file;private boolean working;private LinearLayout body;
 @Override public void onCreate(Bundle b){super.onCreate(b);if(b!=null){source=b.getString("source","이전 앱");String p=b.getString("file","");if(!p.isEmpty())file=new File(p);String saved=b.getString("mapping","");try{org.json.JSONObject o=new org.json.JSONObject(saved);Iterator<String> keys=o.keys();while(keys.hasNext()){String key=keys.next();mapping.put(key,o.getString(key));}}catch(Exception ignored){}}build();if(file!=null)load(true);}
 private void build(){LinearLayout page=new LinearLayout(this);page.setOrientation(1);page.setBackgroundColor(AppTheme.surface(this));page.setPadding(Ui.dp(this,12),Ui.dp(this,4),Ui.dp(this,12),Ui.dp(this,4));LinearLayout top=new LinearLayout(this);Button back=Ui.button(this,"‹ 목록");back.setOnClickListener(v->finish());top.addView(back);top.addView(Ui.text(this,"다른 앱 자료 가져오기",18,true),Ui.weight(1));page.addView(top);ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);scroll.addView(body);page.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));body.addView(Ui.text(this,"1. 이전 앱에서 내보낸 샘플 또는 전체 파일을 선택하세요.\n2. 첫 줄의 열을 우리 앱 항목과 연결하세요.\n3. 미리보기 확인 후 가져오세요.\nExcel(.xlsx), CSV · 사진은 범용 자동 연결 대상에 포함되지 않습니다.",13,false));Button choose=Ui.primary(this,"샘플 / 전체 파일 선택");body.addView(choose);choose.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,1);});Ui.setContentView(this,page);}
 private void load(boolean restored){ProgressDialog p=ProgressDialog.show(this,"자료 읽기","열과 샘플을 읽고 있습니다…",true,false);working=true;new Thread(()->{try{List<Map<String,String>> read=GenericImport.read(file);if(read.isEmpty())throw new Exception("샘플 명함이 없습니다.");runOnUiThread(()->{working=false;p.dismiss();if(isFinishing()||isDestroyed())return;rows=read;headers=new ArrayList<>(rows.get(0).keySet());if(!restored){mapping.clear();mapping.putAll(GenericImport.suggest(this,headers));}showMapping();});}catch(Exception e){runOnUiThread(()->{working=false;p.dismiss();error(e);});}}).start();}
 private void showMapping(){build();body.addView(Ui.section(this,rows.size()+"명 · 열 연결"));EditText sourceInput=Ui.edit(this,"이전 사용 앱 이름");sourceInput.setText(source);sourceInput.setContentDescription("가져온 앱 이름");body.addView(sourceInput);sourceInput.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int d){}public void onTextChanged(CharSequence s,int a,int b,int c){source=s.toString();}public void afterTextChanged(android.text.Editable e){}});
  List<String[]> cols=DataExchange.columns();String[] labels=new String[cols.size()+1];labels[0]="가져오지 않음";for(int i=0;i<cols.size();i++)labels[i+1]=cols.get(i)[0];
  for(String h:headers){body.addView(Ui.label(this,h+" · 예: "+sample(rows.get(0).get(h))));Spinner spinner=new Spinner(this);spinner.setContentDescription(h+" 연결 항목");spinner.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,labels));int selected=0;for(int i=0;i<cols.size();i++)if(cols.get(i)[1].equals(mapping.get(h)))selected=i+1;spinner.setSelection(selected);spinner.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int position,long id){if(position==0)mapping.remove(h);else mapping.put(h,cols.get(position-1)[1]);}});body.addView(spinner,new LinearLayout.LayoutParams(-1,Ui.dp(this,44)));}
  Button preview=Ui.primary(this,"연결 결과 미리보기");body.addView(preview);preview.setOnClickListener(v->preview());}
 private String sample(String s){return s==null?"":s.length()>50?s.substring(0,50)+"…":s;}
 private void preview(){try{GenericImport.validate(mapping);StringBuilder text=new StringBuilder("전체 "+rows.size()+"명 · 앞 3명 미리보기\n원래 생성일을 유지하고 기존 명함의 빈 항목만 병합합니다.\n\n");for(int i=0;i<Math.min(3,rows.size());i++){Contact c=GenericImport.convert(rows.get(i),mapping,source);text.append(i+1).append(".\n");for(String[] col:DataExchange.columns())if(!c.get(col[1]).isEmpty())text.append(col[0]).append(": ").append(c.get(col[1])).append('\n');text.append('\n');}TextView view=Ui.text(this,text.toString(),14,false);ScrollView scroll=new ScrollView(this);scroll.setPadding(20,8,20,8);scroll.addView(view);new AlertDialog.Builder(this).setTitle("가져오기 미리보기").setView(scroll).setNegativeButton("연결 수정",null).setNeutralButton("연결 설정만 저장",(d,w)->{getSharedPreferences("imports",0).edit().putString(GenericImport.key(headers),new org.json.JSONObject(mapping).toString()).apply();Toast.makeText(this,"같은 열 구성의 다음 파일에 사용할 설정을 저장했습니다.",1).show();}).setPositiveButton("확인 후 가져오기",(d,w)->apply()).show();}catch(Exception e){error(e);}}
 private void apply(){if(working)return;working=true;Map<String,String> confirmed=new LinkedHashMap<>(mapping);ProgressDialog p=ProgressDialog.show(this,"가져오기","기존 명함과 비교하며 저장합니다…",true,false);new Thread(()->{DbHelper db=new DbHelper(this);try{int[] count=GenericImport.apply(this,db,rows,confirmed,source);runOnUiThread(()->{working=false;p.dismiss();new AlertDialog.Builder(this).setTitle("가져오기 완료").setMessage("신규 "+count[0]+"명 / 기존 병합 "+count[1]+"명 / 빈 자료 제외 "+count[2]+"명").setPositiveButton("확인",(d,w)->finish()).show();});}catch(Exception e){runOnUiThread(()->{working=false;p.dismiss();error(e);});}finally{db.close();}}).start();}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==1&&result==RESULT_OK&&data!=null&&data.getData()!=null)try{file=BackupManager.copyUriToCache(this,data.getData(),"generic_import_"+System.currentTimeMillis());load(false);}catch(Exception e){error(e);}}
 @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putString("source",source);b.putString("file",file==null?"":file.getAbsolutePath());b.putString("mapping",new org.json.JSONObject(mapping).toString());}
 private void error(Exception e){if(!isFinishing()&&!isDestroyed())new AlertDialog.Builder(this).setTitle("자료 확인 필요").setMessage(e.getMessage()).setPositiveButton("확인",null).show();}
}
